function recomputeLevels(seam: ISqlSeam): Observable<void> {
  const sql = `DELETE FROM "fetch_result_error";\nINSERT OR IGNORE INTO "fetch_result_error" ("endpoint", "status") SELECT b0."endpoint", b0."status" FROM "resp_raw" b0 WHERE (b0."status" >= 400);\nDELETE FROM "fetch_result_fresh";\nINSERT OR IGNORE INTO "fetch_result_fresh" ("endpoint", "tag", "body") SELECT b0."endpoint", b0."tag", b0."body" FROM "resp_raw" b0 WHERE (b0."status" = 200);\nDELETE FROM "fetch_result_unchanged";\nINSERT OR IGNORE INTO "fetch_result_unchanged" ("endpoint") SELECT b0."endpoint" FROM "resp_raw" b0 WHERE (b0."status" = 304)`;
  return seam.runner.executeMultiple(seam.db, sql);
}

function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const fetch_result_error = multisetDiff(before.fetch_result_error, after.fetch_result_error);
  const fetch_result_fresh = multisetDiff(before.fetch_result_fresh, after.fetch_result_fresh);
  const fetch_result_unchanged = multisetDiff(before.fetch_result_unchanged, after.fetch_result_unchanged);
  const resp_raw = multisetDiff(before.resp_raw, after.resp_raw);
  return {
    rels: [
      { rel: "fetch_result_error", add: fetch_result_error.add, del: fetch_result_error.del },
      { rel: "fetch_result_fresh", add: fetch_result_fresh.add, del: fetch_result_fresh.del },
      { rel: "fetch_result_unchanged", add: fetch_result_unchanged.add, del: fetch_result_unchanged.del },
      { rel: "resp_raw", add: resp_raw.add, del: resp_raw.del },
    ],
    carryPending: false,
  };
}

function runNaiveTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // match_classify_response: no edge rules -- absorb arrivals, recompute levels, diff.
}

